/** Local lesson content. Imported data cannot replace the model or run code. */
export const DECK_FORMAT = 'recallweave-deck/1';
export const MAX_DECK_BYTES = 262144;

function deckRecord(value, path) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${path} must be an object.`);
  }
  return value;
}

function deckText(value, path, limit) {
  if (typeof value !== 'string' || !value.trim() || value.length > limit) {
    throw new Error(`${path} must be nonempty text of at most ${limit} characters.`);
  }
  return value;
}

function deckList(value, path, minimum, maximum) {
  if (!Array.isArray(value) || value.length < minimum || value.length > maximum) {
    throw new Error(`${path} must contain ${minimum}–${maximum} entries.`);
  }
  return value;
}

/** Validate and copy only the content fields used by the existing lesson runtime. */
export function validateDeck(value) {
  const input = deckRecord(value, 'Deck');
  if (input.format !== undefined && input.format !== DECK_FORMAT) {
    throw new Error(`Unsupported deck format. Use ${DECK_FORMAT}.`);
  }
  const title = deckText(input.title, 'title', 160);
  const attribution = deckText(input.attribution, 'attribution', 2000);
  const license = deckText(input.license, 'license', 2000);
  const concepts = deckList(input.concepts, 'concepts', 1, 32).map((concept, index) =>
    deckText(concept, `concepts[${index}]`, 80));
  if (new Set(concepts).size !== concepts.length) throw new Error('Concept names must be unique.');
  const knownConcepts = new Set(concepts);
  const ids = new Set();
  const coveredConcepts = new Set();
  const links = new Map(concepts.map(concept => [concept, new Set()]));
  const items = deckList(input.items, 'items', 1, 100).map((value, index) => {
    const path = `items[${index}]`;
    const item = deckRecord(value, path);
    const id = deckText(item.id, `${path}.id`, 80);
    if (ids.has(id)) throw new Error(`${path}.id duplicates another question ID.`);
    ids.add(id);
    const concept = deckText(item.concept, `${path}.concept`, 80);
    if (!knownConcepts.has(concept)) throw new Error(`${path}.concept is not in concepts.`);
    coveredConcepts.add(concept);
    const prerequisites = deckList(item.prerequisites, `${path}.prerequisites`, 0, 31).map((name, p) => {
      deckText(name, `${path}.prerequisites[${p}]`, 80);
      if (!knownConcepts.has(name)) throw new Error(`${path}.prerequisites contains an unknown concept.`);
      if (name === concept) throw new Error(`${path} cannot require its own concept.`);
      links.get(concept).add(name);
      return name;
    });
    if (new Set(prerequisites).size !== prerequisites.length) throw new Error(`${path}.prerequisites contains a duplicate.`);
    const options = deckList(item.options, `${path}.options`, 2, 6).map((option, o) =>
      deckText(option, `${path}.options[${o}]`, 1000));
    if (new Set(options).size !== options.length) throw new Error(`${path}.options must be distinct.`);
    if (!Number.isInteger(item.answer) || item.answer < 0 || item.answer >= options.length) {
      throw new Error(`${path}.answer must be a zero-based index of an option.`);
    }
    return Object.freeze({
      id, concept, prerequisites: Object.freeze(prerequisites),
      prompt: deckText(item.prompt, `${path}.prompt`, 2000),
      options: Object.freeze(options), answer: item.answer,
      explanation: deckText(item.explanation, `${path}.explanation`, 4000),
      transfer: deckText(item.transfer, `${path}.transfer`, 2000)
    });
  });
  if (coveredConcepts.size !== concepts.length) throw new Error('Every concept must have at least one question.');
  const visiting = new Set();
  const visited = new Set();
  const visit = concept => {
    if (visiting.has(concept)) throw new Error('Prerequisite links must not form a cycle.');
    if (visited.has(concept)) return;
    visiting.add(concept);
    for (const prerequisite of links.get(concept)) visit(prerequisite);
    visiting.delete(concept);
    visited.add(concept);
  };
  concepts.forEach(visit);
  return Object.freeze({
    format: DECK_FORMAT, title, attribution, license,
    concepts: Object.freeze(concepts), items: Object.freeze(items)
  });
}

/** The same size limit applies to a File and to programmatically supplied UTF-8 JSON. */
export function parseDeck(text) {
  if (typeof text !== 'string' || new TextEncoder().encode(text).length > MAX_DECK_BYTES) {
    throw new Error('Choose a JSON deck no larger than 256 KiB.');
  }
  let value;
  try { value = JSON.parse(text); }
  catch { throw new Error('The file is not valid JSON. Check its commas, quotes and brackets.'); }
  return validateDeck(value);
}

/** Export the existing bundled lesson as an editable example of the same contract. */
export function serializeDeck(deck) {
  return JSON.stringify(validateDeck(deck), null, 2) + '\n';
}

/**
 * Transparent Bayesian Knowledge Tracing and adaptive item selection.
 * Parameters are pedagogical defaults, not fitted or validated estimates.
 * @typedef {{id:string, concept:string, prerequisites:string[], options:string[], answer:number, prompt:string, explanation:string, transfer:string}} Item
 * @typedef {{initial:number, learn:number, guess:number, slip:number}} BktParameters
 */
export const DEFAULT_BKT = Object.freeze({ initial: 0.22, learn: 0.18, guess: 0.2, slip: 0.1 });
const clamp = (value, min = 0, max = 1) => Math.min(max, Math.max(min, value));

/** Bernoulli entropy in bits. @param {number} p */
export function entropy(p) {
  const q = clamp(p);
  if (q === 0 || q === 1) return 0;
  return -q * Math.log2(q) - (1 - q) * Math.log2(1 - q);
}

/**
 * One BKT update. Correctness is evidence, not certainty; a guess and a slip remain possible.
 * @param {number} prior
 * @param {boolean} correct
 * @param {BktParameters} parameters
 */
export function updateMastery(prior, correct, parameters = DEFAULT_BKT) {
  const p = clamp(prior);
  const { guess, slip, learn } = parameters;
  for (const [key, value] of Object.entries(parameters)) {
    if (!Number.isFinite(value) || value < 0 || value > 1) throw new RangeError(`${key} must be in [0,1]`);
  }
  const pCorrect = p * (1 - slip) + (1 - p) * guess;
  const posterior = correct ? p * (1 - slip) / pCorrect : p * slip / (p * slip + (1 - p) * (1 - guess));
  return clamp(posterior + (1 - posterior) * learn);
}

/** Expected reduction in uncertainty from an item response under its concept mastery.
 * @param {number} mastery
 * @param {BktParameters} parameters
 */
export function expectedInformationGain(mastery, parameters = DEFAULT_BKT) {
  const p = clamp(mastery);
  const { guess, slip } = parameters;
  const pCorrect = p * (1 - slip) + (1 - p) * guess;
  const correctPosterior = p * (1 - slip) / pCorrect;
  const wrongPosterior = p * slip / (p * slip + (1 - p) * (1 - guess));
  return Math.max(0, entropy(p) - pCorrect * entropy(correctPosterior) - (1 - pCorrect) * entropy(wrongPosterior));
}

/**
 * Select an unseen item maximizing uncertainty reduction plus prerequisite repair.
 * Default ties use the current locale's item-id order. A recorded ID may choose
 * another exact maximum-score tie without changing the default choice.
 * @param {Item[]} items
 * @param {Set<string>} asked
 * @param {Record<string,number>} mastery
 * @param {BktParameters} parameters
 * @param {string} [preferredItemId] recorded identity, honored only at the exact maximum score
 * @returns {Item|null}
 */
export function selectNextItem(items, asked, mastery, parameters = DEFAULT_BKT, preferredItemId) {
  const candidates = items.filter(item => !asked.has(item.id));
  if (!candidates.length) return null;
  const score = item => {
    const m = mastery[item.concept] ?? parameters.initial;
    // Prefer a weak concept that unlocks several still-unanswered downstream ideas.
    const downstream = candidates.filter(next => next.id !== item.id && next.prerequisites.includes(item.concept)).length;
    const prerequisiteRepair = (1 - m) * Math.min(3, downstream) * 0.12;
    return expectedInformationGain(m, parameters) + prerequisiteRepair;
  };
  const selected = candidates.sort((a, b) => score(b) - score(a) || a.id.localeCompare(b.id))[0];
  if (preferredItemId === undefined) return selected;
  const preferred = candidates.find(item => item.id === preferredItemId);
  return preferred && score(preferred) === score(selected) ? preferred : selected;
}

/** Clone session probabilities so learners' local run has no shared state. */
export function initialMastery(concepts, parameters = DEFAULT_BKT) {
  return Object.fromEntries(concepts.map(concept => [concept, parameters.initial]));
}

/**
 * Reproducible toy learner run; simulated evidence is never real learner data.
 * @param {Item[]} items
 * @param {string[]} concepts
 * @param {Record<string,number>} latentKnowledge simulated probability of knowing each concept
 * @param {boolean} adaptive use the information-gain selector, or fixed deck order
 * @param {number} seed deterministic pseudo-random seed
 */
export function runLearnerSimulation(items, concepts, latentKnowledge, adaptive = true, seed = 20261005) {
  let state = seed >>> 0 || 1;
  const random = () => {
    state ^= state << 13; state ^= state >>> 17; state ^= state << 5;
    return (state >>> 0) / 4294967296;
  };
  const stateByConcept = initialMastery(concepts);
  const asked = new Set();
  const trace = [];
  while (asked.size < items.length) {
    const item = adaptive ? selectNextItem(items, asked, stateByConcept) : items.find(candidate => !asked.has(candidate.id));
    const knowledge = clamp(latentKnowledge[item.concept] ?? 0.5);
    const correct = random() < 0.18 + knowledge * 0.72;
    asked.add(item.id);
    stateByConcept[item.concept] = updateMastery(stateByConcept[item.concept], correct);
    trace.push({ item: item.id, concept: item.concept, correct });
  }
  const meanEstimatedMastery = concepts.reduce((sum, concept) => sum + stateByConcept[concept], 0) / concepts.length;
  return { trace, mastery: stateByConcept, meanEstimatedMastery };
}

/**
 * A local review snapshot and one bounded practice round.
 * Practice never updates the original answers or the knowledge model.
 */

function validChoice(item, choice) {
  if (!Number.isInteger(choice) || choice < 0 || choice >= item.options.length) {
    throw new RangeError('Choose one of this question’s answer options.');
  }
}

/** Keep the first-attempt order, chosen answer and explanation available for review. */
export function createReview(items, answers) {
  const byId = new Map(items.map(item => [item.id, item]));
  const seen = new Set();
  return Object.freeze(answers.map(answer => {
    const item = byId.get(answer.item);
    if (!item || seen.has(item.id)) throw new RangeError('Review needs one first answer per known question.');
    seen.add(item.id);
    validChoice(item, answer.choice);
    return Object.freeze({
      id: item.id,
      concept: item.concept,
      prompt: item.prompt,
      options: Object.freeze([...item.options]),
      answer: item.answer,
      choice: answer.choice,
      correct: answer.choice === item.answer,
      explanation: item.explanation,
      transfer: item.transfer
    });
  }));
}

/** Each initially missed question gets one retry, in its original session order. */
export function beginPractice(review) {
  return Object.freeze({
    items: Object.freeze(review.filter(item => !item.correct)),
    answers: Object.freeze([])
  });
}

export function currentPracticeItem(round) {
  return round.items[round.answers.length] ?? null;
}

/** Return new practice state; both the review and earlier round states stay intact. */
export function answerPractice(round, itemId, choice) {
  const item = currentPracticeItem(round);
  if (!item || item.id !== itemId) throw new RangeError('Only the current unanswered practice question can be answered.');
  validChoice(item, choice);
  return Object.freeze({
    items: round.items,
    answers: Object.freeze([...round.answers, Object.freeze({item: item.id, choice, correct: choice === item.answer})])
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { DECK_FORMAT, MAX_DECK_BYTES, parseDeck, serializeDeck, validateDeck } from '../src/deck.mjs';
import { initialMastery, selectNextItem, updateMastery } from '../src/knowledge.mjs';
import { createReview, beginPractice, answerPractice } from '../src/review.mjs';

const bundled = JSON.parse(await readFile(new URL('../data/deck.json', import.meta.url), 'utf8'));
const example = () => ({
  format: DECK_FORMAT, title: 'Workshop decisions', attribution: 'Original test fixture', license: 'Test fixture',
  concepts: ['observation', 'decision'],
  items: [
    {id:'observe', concept:'observation', prerequisites:[], prompt:'What did you observe?', options:['Guess', 'Read the record'], answer:1, explanation:'Use the record.', transfer:'Describe one observation.'},
    {id:'decide', concept:'decision', prerequisites:['observation'], prompt:'Which action follows?', options:['Ignore it', 'Guess again', 'Use the observation'], answer:2, explanation:'Connect action to observation.', transfer:'Name the connection.'}
  ]
});

test('the existing bundled deck imports unchanged without a format field', () => {
  const deck = parseDeck(JSON.stringify(bundled));
  assert.equal(deck.format, DECK_FORMAT);
  assert.deepEqual(deck.items, bundled.items);
  assert.deepEqual(deck.concepts, bundled.concepts);
  assert.equal(deck.title, bundled.title);
  assert.equal(deck.attribution, bundled.attribution);
  assert.equal(deck.license, bundled.license);
});

test('a deck is an immutable copy, and unknown fields cannot configure the runtime', () => {
  const source = example();
  source.parameters = {initial:1, guess:0};
  source.items[0].correct = true;
  const deck = validateDeck(source);
  source.concepts.push('another');
  source.items[0].answer = 0;
  source.items[0].options[1] = 'changed';
  source.items[1].prerequisites.length = 0;
  assert.equal(deck.items[0].answer, 1);
  assert.equal(deck.items[0].options[1], 'Read the record');
  assert.deepEqual(deck.items[1].prerequisites, ['observation']);
  assert.deepEqual(deck.concepts, ['observation', 'decision']);
  assert.equal(Object.hasOwn(deck, 'parameters'), false);
  assert.equal(Object.hasOwn(deck.items[0], 'correct'), false);
  for (const value of [deck, deck.concepts, deck.items, ...deck.items, ...deck.items.flatMap(item => [item.options, item.prerequisites])]) {
    assert.equal(Object.isFrozen(value), true);
  }
  assert.throws(() => {deck.items[0].answer = 0;}, TypeError);
});

test('malformed JSON, unsupported versions and wrong top-level values give actionable errors', () => {
  assert.throws(() => parseDeck('{'), /not valid JSON/);
  for (const value of [null, [], 0, 'deck']) assert.throws(() => validateDeck(value), /must be an object/);
  const source = example();
  source.format = 'recallweave-deck/2';
  assert.throws(() => validateDeck(source), /Unsupported deck format/);
});

test('JSON byte limit counts multibyte text and accepts the exact boundary', () => {
  const json = JSON.stringify(example());
  const bytes = new TextEncoder().encode(json).length;
  assert.equal(parseDeck(json + ' '.repeat(MAX_DECK_BYTES - bytes)).title, example().title);
  assert.throws(() => parseDeck(json + ' '.repeat(MAX_DECK_BYTES - bytes + 1)), /256 KiB/);
  const large = {...example(), title:'é'.repeat(80), extra:'é'.repeat(MAX_DECK_BYTES / 2)};
  assert.throws(() => parseDeck(JSON.stringify(large)), /256 KiB/);
});

test('required readable metadata and bounded question fields are validated', () => {
  for (const key of ['title', 'attribution', 'license']) {
    for (const value of [undefined, '', '   ', 12, {}]) {
      const source = example(); source[key] = value;
      assert.throws(() => validateDeck(source), new RegExp(key));
    }
  }
  for (const [key, limit] of [['id',80], ['prompt',2000], ['explanation',4000], ['transfer',2000]]) {
    const source = example(); source.items[0][key] = 'x'.repeat(limit + 1);
    assert.throws(() => validateDeck(source), new RegExp(key));
  }
  const tooLong = example(); tooLong.title = 'x'.repeat(161);
  assert.throws(() => validateDeck(tooLong), /title/);
});

test('empty and oversized collections and duplicate identities are refused', () => {
  for (const key of ['concepts', 'items']) {
    const source = example(); source[key] = [];
    assert.throws(() => validateDeck(source), new RegExp(key));
  }
  const tooManyConcepts = example(); tooManyConcepts.concepts = Array.from({length:33}, (_,i) => `c${i}`);
  assert.throws(() => validateDeck(tooManyConcepts), /concepts/);
  const tooManyItems = example(); tooManyItems.items = Array.from({length:101}, (_,i) => ({...tooManyItems.items[0], id:`q${i}`}));
  assert.throws(() => validateDeck(tooManyItems), /items/);
  const duplicateConcept = example(); duplicateConcept.concepts.push('observation');
  assert.throws(() => validateDeck(duplicateConcept), /unique/);
  const duplicateItem = example(); duplicateItem.items[1].id = 'observe';
  assert.throws(() => validateDeck(duplicateItem), /duplicates/);
});

test('every question and prerequisite must name a known covered concept', () => {
  const unknown = example(); unknown.items[0].concept = 'missing';
  assert.throws(() => validateDeck(unknown), /not in concepts/);
  const prerequisite = example(); prerequisite.items[1].prerequisites = ['missing'];
  assert.throws(() => validateDeck(prerequisite), /unknown concept/);
  const uncovered = example(); uncovered.concepts.push('uncovered');
  assert.throws(() => validateDeck(uncovered), /at least one question/);
  const repeated = example(); repeated.items[1].prerequisites.push('observation');
  assert.throws(() => validateDeck(repeated), /duplicate/);
});

test('self-requirements and concept cycles across different questions are refused', () => {
  const self = example(); self.items[0].prerequisites = ['observation'];
  assert.throws(() => validateDeck(self), /own concept/);
  const cycle = example(); cycle.items[0].prerequisites = ['decision'];
  assert.throws(() => validateDeck(cycle), /cycle/);
  const crossQuestion = example();
  crossQuestion.items.push({...crossQuestion.items[0], id:'another', prerequisites:['decision']});
  assert.throws(() => validateDeck(crossQuestion), /cycle/);
});

test('choices require distinct readable options and an actual integer answer index', () => {
  for (const answer of [-1, 2, 0.5, '1', null, true, NaN]) {
    const source = example(); source.items[0].answer = answer;
    assert.throws(() => validateDeck(source), /zero-based index/);
  }
  for (const options of [[], ['only'], ['same','same'], ['yes',''], ['yes',{}], Array.from({length:7}, (_,i) => String(i))]) {
    const source = example(); source.items[0].options = options;
    assert.throws(() => validateDeck(source), /options/);
  }
});

test('100 questions and 32 concepts work through the existing selector to exhaustion', () => {
  const source = example();
  source.concepts = Array.from({length:32}, (_,i) => `c${i}`);
  source.items = Array.from({length:100}, (_,i) => ({...source.items[0], id:`q${String(i).padStart(3,'0')}`, concept:`c${i % 32}`, prerequisites:i % 32 ? [`c${i % 32 - 1}`] : []}));
  const deck = validateDeck(source);
  const mastery = initialMastery(deck.concepts);
  const asked = new Set();
  for (let i=0; i<100; i++) {
    const item = selectNextItem(deck.items, asked, mastery);
    assert.ok(item);
    assert.equal(asked.has(item.id), false);
    asked.add(item.id);
    mastery[item.concept] = updateMastery(mastery[item.concept], i % 2 === 0);
  }
  assert.equal(selectNextItem(deck.items, asked, mastery), null);
  assert.equal(asked.size, 100);
  assert.ok(Object.values(mastery).every(value => value >= 0 && value <= 1));
});

test('imported answer indices, literal text and object-key names survive learning and practice', () => {
  const source = example();
  source.title = '<img src=x onerror="alert(1)">';
  source.concepts = ['__proto__', 'constructor'];
  source.items[0].id = '__proto__';
  source.items[0].concept = '__proto__';
  source.items[1].concept = 'constructor';
  source.items[1].prerequisites = ['__proto__'];
  source.items[0].options[1] = '<b>Literal answer</b>';
  const deck = parseDeck(JSON.stringify(source));
  assert.equal(deck.title, source.title);
  const mastery = initialMastery(deck.concepts);
  const asked = new Set();
  const answers = [];
  for (let item; (item = selectNextItem(deck.items, asked, mastery));) {
    asked.add(item.id);
    const choice = item.id === '__proto__' ? 0 : item.answer;
    const correct = choice === item.answer;
    answers.push({item:item.id, concept:item.concept, choice, correct});
    mastery[item.concept] = updateMastery(mastery[item.concept], correct);
  }
  const review = createReview(deck.items, answers);
  assert.equal(review[0].id, '__proto__');
  assert.equal(review[0].options[review[0].answer], '<b>Literal answer</b>');
  assert.deepEqual(review.map(item => item.correct), [false, true]);
  const practice = answerPractice(beginPractice(review), '__proto__', 1);
  assert.equal(practice.answers[0].correct, true);
  assert.equal(review[0].correct, false);
  assert.equal(Object.hasOwn(mastery, '__proto__'), true);
  assert.equal(typeof mastery.__proto__, 'number');
});

test('downloadable example round-trips through the import contract with full attribution', () => {
  const text = serializeDeck(bundled);
  const deck = parseDeck(text);
  assert.equal(deck.format, DECK_FORMAT);
  assert.deepEqual(deck.items, bundled.items);
  assert.equal(deck.attribution, bundled.attribution);
  assert.equal(deck.license, bundled.license);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { DEFAULT_BKT, entropy, expectedInformationGain, initialMastery, runLearnerSimulation, selectNextItem, updateMastery } from '../src/knowledge.mjs';

const items = [
  {id:'a',concept:'a',prerequisites:[],options:[],answer:0,prompt:'',explanation:'',transfer:''},
  {id:'b',concept:'b',prerequisites:['a'],options:[],answer:0,prompt:'',explanation:'',transfer:''}
];
test('BKT probabilities stay bounded across repeated evidence', () => {
  for (const first of [0, .01, .22, .5, .99, 1]) {
    let p = first;
    for (let i = 0; i < 200; i++) {
      p = updateMastery(p, i % 2 === 0);
      assert.ok(p >= 0 && p <= 1 && Number.isFinite(p));
    }
  }
});
test('correct evidence raises and incorrect evidence lowers posterior for interior prior', () => {
  const prior = .4;
  assert.ok(updateMastery(prior, true) > prior);
  assert.ok(updateMastery(prior, false) < prior);
});
test('parameter validation rejects impossible probabilities', () => {
  assert.throws(() => updateMastery(.5, true, {...DEFAULT_BKT, guess: 2}), RangeError);
});
test('entropy and information gain have expected bounds and peak near uncertainty', () => {
  assert.equal(entropy(0), 0);
  assert.equal(entropy(1), 0);
  assert.equal(entropy(.5), 1);
  assert.ok(expectedInformationGain(.5) > expectedInformationGain(.01));
  for (let i = 0; i <= 1000; i++) {
    const gain = expectedInformationGain(i / 1000);
    assert.ok(gain >= 0 && gain <= 1);
  }
});
test('selector prioritizes a weak prerequisite and is stable after exhaustion', () => {
  const mastery = {a:.1,b:.9};
  const first = selectNextItem(items, new Set(), mastery);
  assert.equal(first.id, 'a');
  assert.equal(selectNextItem(items, new Set(['a']), mastery).id, 'b');
  assert.equal(selectNextItem(items, new Set(['a','b']), mastery), null);
});
test('initial mastery creates independent named concept values', () => {
  assert.deepEqual(initialMastery(['a','b']), {a:.22,b:.22});
});
test('scripted learner simulation is deterministic, bounded, and distinguishes selector modes', () => {
  const truth = {a:.8,b:.4};
  const adaptive = runLearnerSimulation(items, ['a','b'], truth, true, 41);
  const repeated = runLearnerSimulation(items, ['a','b'], truth, true, 41);
  const fixed = runLearnerSimulation([...items].reverse(), ['a','b'], truth, false, 41);
  assert.deepEqual(adaptive, repeated);
  assert.equal(adaptive.trace.length, items.length);
  assert.equal(new Set(adaptive.trace.map(row => row.item)).size, items.length);
  assert.ok(adaptive.meanEstimatedMastery >= 0 && adaptive.meanEstimatedMastery <= 1);
  assert.notDeepEqual(adaptive.trace.map(row => row.item), fixed.trace.map(row => row.item));
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { answerPractice, beginPractice, createReview, currentPracticeItem } from '../src/review.mjs';

const item = (id, answer = 1) => ({
  id, concept: 'energy', prompt: `Prompt ${id}`, options: ['First', 'Second', 'Third'],
  answer, explanation: `Explanation ${id}`, transfer: `Transfer ${id}`
});
const items = [item('a'), item('b', 2), item('c', 0)];
const answers = [{item: 'b', choice: 0}, {item: 'a', choice: 1}, {item: 'c', choice: 2}];

test('review preserves session order and the actual chosen answer', () => {
  const review = createReview(items, answers);
  assert.deepEqual(review.map(row => [row.id, row.choice, row.correct]), [
    ['b', 0, false], ['a', 1, true], ['c', 2, false]
  ]);
  assert.equal(review[0].options[review[0].choice], 'First');
  assert.equal(review[0].options[review[0].answer], 'Third');
  assert.equal(review[0].explanation, 'Explanation b');
  assert.equal(review[0].transfer, 'Transfer b');
});

test('review is an immutable snapshot independent of mutable input arrays', () => {
  const sourceItems = structuredClone(items);
  const sourceAnswers = structuredClone(answers);
  const review = createReview(sourceItems, sourceAnswers);
  sourceItems[1].options[0] = 'Rewritten';
  sourceItems[1].prompt = 'Rewritten';
  sourceAnswers[0].choice = 2;
  sourceAnswers.reverse();
  assert.equal(review[0].prompt, 'Prompt b');
  assert.equal(review[0].options[0], 'First');
  assert.equal(review[0].choice, 0);
  assert.throws(() => { review[0].correct = true; }, TypeError);
  assert.throws(() => { review[0].options[0] = 'Other'; }, TypeError);
  assert.throws(() => review.push(review[0]), TypeError);
});

test('a review rejects unknown, duplicate, or invalid first answers', () => {
  assert.throws(() => createReview(items, [{item: 'missing', choice: 0}]), RangeError);
  assert.throws(() => createReview(items, [answers[0], answers[0]]), RangeError);
  for (const choice of [-1, 3, 0.5, NaN, '0', null]) {
    assert.throws(() => createReview(items, [{item: 'a', choice}]), RangeError);
  }
});

test('practice includes only initially missed questions in first-attempt order', () => {
  const review = createReview(items, answers);
  const before = JSON.stringify(review);
  const round = beginPractice(review);
  assert.deepEqual(round.items.map(row => row.id), ['b', 'c']);
  assert.equal(currentPracticeItem(round).id, 'b');
  assert.equal(JSON.stringify(review), before);
});

test('correct and incorrect retries remain separate from the immutable original trace', () => {
  const review = createReview(items, answers);
  const before = JSON.stringify(review);
  const start = beginPractice(review);
  const first = answerPractice(start, 'b', 2);
  const complete = answerPractice(first, 'c', 1);
  assert.equal(start.answers.length, 0);
  assert.equal(first.answers.length, 1);
  assert.deepEqual(complete.answers, [
    {item: 'b', choice: 2, correct: true}, {item: 'c', choice: 1, correct: false}
  ]);
  assert.equal(currentPracticeItem(complete), null);
  assert.equal(JSON.stringify(review), before);
  assert.throws(() => { complete.answers[0].correct = false; }, TypeError);
  assert.throws(() => complete.items.reverse(), TypeError);
});

test('practice resumes at the next unanswered question and refuses duplicate or out-of-order writes', () => {
  const start = beginPractice(createReview(items, answers));
  assert.throws(() => answerPractice(start, 'c', 0), RangeError);
  const paused = answerPractice(start, 'b', 0);
  assert.equal(currentPracticeItem(paused).id, 'c');
  assert.throws(() => answerPractice(paused, 'b', 2), RangeError);
  for (const choice of [-1, 3, 1.5, Infinity, '1']) {
    assert.throws(() => answerPractice(paused, 'c', choice), RangeError);
  }
  const complete = answerPractice(paused, 'c', 0);
  assert.throws(() => answerPractice(complete, 'c', 0), RangeError);
  assert.equal(paused.answers.length, 1);
});

test('an all-correct or empty review has no practice question', () => {
  for (const firstAnswers of [[], items.map(row => ({item: row.id, choice: row.answer}))]) {
    const round = beginPractice(createReview(items, firstAnswers));
    assert.equal(round.items.length, 0);
    assert.equal(currentPracticeItem(round), null);
    assert.throws(() => answerPractice(round, 'a', 1), RangeError);
  }
});
